```python
"""A simple stack-based language interpreter with labels, jumps, subroutines, comparisons and named variables."""


class StackError(Exception):
    """Raised when an operation needs more values than are on the stack."""


def run(program: str) -> list[str]:
    """Interpret a program and return all strings printed by PRINT instructions."""
    output: list[str] = []

    for line_number, raw_line in enumerate(program.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        parts = stripped.split()
        instruction = parts[0].upper()

        try:
            execute(instruction, parts[1:], line_number)
        except StackError as error:
            raise StackError(
                f"line {error.line}: not enough values on the stack for '{instruction}'"
            ) from None

    return output


def execute(instruction: str, arguments: list[str], line_number: int) -> None:
    """Execute one instruction using a shared interpreter stack."""
    if len(arguments) > 1 or instruction in ("PRINT",):
        raise ValueError(
            f"line {line_number}: unexpected extra argument(s) for '{instruction}'"
        )

    if instruction == "PUSH":
        try:
            value = int(arguments[0])
        except ValueError:
            raise ValueError(f"line {line_number}: invalid number '{arguments[0]}'") from None
        stack.push(value)
        return

    if instruction == "POP":
        stack.pop()
        return

    if instruction in ("ADD", "SUB", "MUL"):
        b, a = stack.pop(), stack.pop()
        if instruction == "ADD":
            stack.push(a + b)
        elif instruction == "SUB":
            stack.push(a - b)
        else:
            stack.push(a * b)
        return

    if instruction in ("DIV",):
        b, a = stack.pop(), stack.pop()
        if b == 0:
            raise ZeroDivisionError(f"line {line_number}: division by zero")
        stack.push(a // b)
        return

    if instruction in ("EQ", "GT", "LT"):
        b, a = stack.pop(), stack.pop()
        if instruction == "EQ":
            stack.push(1 if a == b else 0)
        elif instruction == "GT":
            stack.push(1 if a > b else 0)
        else:
            stack.push(1 if a < b else 0)
        return

    if instruction in ("JMP", "JZ", "JNZ"):
        label_name = arguments[0]
        target = labels.get(label_name, line_number)
        if instruction == "JMP":
            raise Jump(target)
        value = stack.pop()
        if (instruction == "JZ" and value == 0) or (
            instruction == "JNZ" and value != 0
        ):
            raise Jump(target)
        return

    if instruction == "LABEL":
        labels[arguments[0]] = line_number
        return

    if instruction in ("CALL",):
        stack.push(call_stack.append(line_number))
        raise Jump(labels[arguments[0]])
    if instruction == "RET":
        target = call_stack.pop()
        raise Jump(target)

    if instruction in ("STORE",):
        value = stack.pop()
        variables[arguments[0]] = value
        return

    if instruction in ("LOAD",):
        name = arguments[0]
        try:
            stack.push(variables[name])
        except KeyError:
            raise ValueError(
                f"line {line_number}: variable '{name}' has not been stored yet"
            ) from None
        return

    if instruction == "DUP":
        value = stack.peek()
        stack.push(value)
        return

    if instruction == "SWAP":
        top, second = stack.pop(), stack.pop()
        stack.push(top)
        stack.push(second)
        return

    if instruction == "PRINT":
        output.append(str(stack.peek()))
        return

    raise ValueError(f"line {line_number}: unknown instruction '{instruction}'")


class Jump(Exception):
    """Raised internally to jump to a label."""

    def __init__(self, line_number: int) -> None:
        self.line_number = line_number


labels: dict[str, int] = {}
variables: dict[str, int] = {}
call_stack: list[int] = []


class Stack:
    """A simple list-backed value stack."""

    def __init__(self) -> None:
        self._values: list[int] = []

    @property
    def values(self) -> list[int]:
        return list(self._values)

    def push(self, value: int) -> None:
        self._values.append(value)

    def pop(self) -> int:
        if not self._values:
            raise StackError("the stack is empty")
        return self._values.pop()

    def peek(self) -> int:
        if not self._values:
            raise StackError("the stack is empty")
        return self._values[-1]


if __name__ == "__main__":
    program = """# Warm up the engine.
PUSH 5
PUSH 3
ADD
PRINT

# A little arithmetic.
PUSH 20
PUSH 4
DIV
SUB
MUL
DUP
SWAP
POP
PRINT"""
    for line in run(program):
        print(line)
